BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @RoleName = UPPER(LTRIM(RTRIM(@RoleName)));

    IF NOT EXISTS
    (
        SELECT 1
        FROM [ethnowear].[Users]
        WHERE [Id] = @UserId
    )
        THROW 51200, 'User does not exist.', 1;

    IF @AssignedByUserId IS NOT NULL
       AND NOT EXISTS
       (
           SELECT 1
           FROM [ethnowear].[Users]
           WHERE [Id] = @AssignedByUserId
       )
        THROW 51201, 'Assigning user does not exist.', 1;

    DECLARE @RoleId BIGINT;

    SELECT @RoleId = [Id]
    FROM [ethnowear].[Roles]
    WHERE [Name] = @RoleName;

    IF @RoleId IS NULL
        THROW 51202, 'Role does not exist.', 1;

    IF NOT EXISTS
    (
        SELECT 1
        FROM [ethnowear].[UserRoles]
        WHERE [UserId] = @UserId
          AND [RoleId] = @RoleId
    )
    BEGIN
        INSERT INTO [ethnowear].[UserRoles]
        (
            [UserId],
            [RoleId],
            [AssignedByUserId]
        )
        VALUES
        (
            @UserId,
            @RoleId,
            @AssignedByUserId
        );
    END;
END;

CREATE PROCEDURE [ethnowear].[AssignUserRole]
    @UserId BIGINT,
    @RoleName NVARCHAR(50),
    @AssignedByUserId BIGINT = NULL
AS

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @Username = LTRIM(RTRIM(@Username));
    SET @FirstName = LTRIM(RTRIM(@FirstName));
    SET @LastName = LTRIM(RTRIM(@LastName));
    SET @Email = NULLIF(LTRIM(RTRIM(@Email)), N'');
    SET @CountryCode = NULLIF(UPPER(LTRIM(RTRIM(@CountryCode))), N'');

    IF @Username IS NULL OR LEN(@Username) NOT BETWEEN 3 AND 100
        THROW 51100, 'Username must contain between 3 and 100 characters.', 1;

    IF @FirstName IS NULL OR LEN(@FirstName) = 0
        THROW 51101, 'First name is required.', 1;

    IF @LastName IS NULL OR LEN(@LastName) = 0
        THROW 51102, 'Last name is required.', 1;

    IF @CountryCode IS NOT NULL AND @CountryCode NOT LIKE '[A-Z][A-Z]'
        THROW 51103, 'Country code must contain two uppercase letters.', 1;

    IF @CreatedByUserId IS NOT NULL
       AND NOT EXISTS
       (
           SELECT 1
           FROM [ethnowear].[Users]
           WHERE [Id] = @CreatedByUserId
       )
        THROW 51104, 'Creating user does not exist.', 1;

    IF EXISTS
    (
        SELECT 1
        FROM [ethnowear].[Users]
        WHERE [NormalizedUsername] = UPPER(@Username)
    )
        THROW 51105, 'Username already exists.', 1;

    IF @Email IS NOT NULL
       AND EXISTS
       (
           SELECT 1
           FROM [ethnowear].[UserInfo]
           WHERE [NormalizedEmail] = UPPER(@Email)
       )
        THROW 51106, 'Email address already exists.', 1;

    BEGIN TRANSACTION;

    INSERT INTO [ethnowear].[Users]
    (
        [Username],
        [PasswordHash],
        [MustChangePassword],
        [TemporaryPasswordExpiresAt],
        [Enabled],
        [CreatedByUserId]
    )
    VALUES
    (
        @Username,
        NULL,
        1,
        NULL,
        0,
        @CreatedByUserId
    );

    SET @UserId = SCOPE_IDENTITY();

    INSERT INTO [ethnowear].[UserInfo]
    (
        [UserId],
        [FirstName],
        [LastName],
        [Email],
        [Phone],
        [AddressLine1],
        [AddressLine2],
        [City],
        [PostalCode],
        [CountryCode]
    )
    VALUES
    (
        @UserId,
        @FirstName,
        @LastName,
        @Email,
        @Phone,
        @AddressLine1,
        @AddressLine2,
        @City,
        @PostalCode,
        @CountryCode
    );

    COMMIT TRANSACTION;

    SELECT @UserId AS [UserId];
END;

CREATE PROCEDURE [ethnowear].[CreateUser]
    @Username NVARCHAR(100),
    @FirstName NVARCHAR(100),
    @LastName NVARCHAR(100),
    @Email NVARCHAR(320) = NULL,
    @Phone NVARCHAR(50) = NULL,
    @AddressLine1 NVARCHAR(250) = NULL,
    @AddressLine2 NVARCHAR(250) = NULL,
    @City NVARCHAR(100) = NULL,
    @PostalCode NVARCHAR(20) = NULL,
    @CountryCode CHAR(2) = NULL,
    @CreatedByUserId BIGINT = NULL,
    @UserId BIGINT = NULL OUTPUT
AS

BEGIN SET NOCOUNT ON; SET XACT_ABORT ON;
IF NOT EXISTS ( SELECT 1 FROM [ethnowear].[Users] WHERE [Id] = @UserId ) THROW 51600, 'User does not exist.', 1;
DECLARE @AdministratorRoleId BIGINT;
SELECT @AdministratorRoleId = [Id] FROM [ethnowear].[Roles] WHERE [Name] = N'ADMINISTRATOR';
IF EXISTS ( SELECT 1 FROM [ethnowear].[Users] AS [users] INNER JOIN [ethnowear].[UserRoles] AS [userRoles] ON [userRoles].[UserId] = [users].[Id] WHERE [users].[Id] = @UserId AND [users].[Enabled] = 1 AND [userRoles].[RoleId] = @AdministratorRoleId ) AND ( SELECT COUNT_BIG(*) FROM [ethnowear].[Users] AS [users] INNER JOIN [ethnowear].[UserRoles] AS [userRoles] ON [userRoles].[UserId] = [users].[Id] WHERE [users].[Enabled] = 1 AND [userRoles].[RoleId] = @AdministratorRoleId ) <= 1 THROW 51601, 'The final enabled administrator cannot be disabled.', 1;
UPDATE [ethnowear].[Users] SET [Enabled] = 0, [TokenVersion] = [TokenVersion] + 1, [UpdatedAt] = SYSUTCDATETIME() WHERE [Id] = @UserId; END;

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF NOT EXISTS
    (
        SELECT 1
        FROM [ethnowear].[Users]
        WHERE [Id] = @UserId
    )
        THROW 51500, 'User does not exist.', 1;

    IF EXISTS
    (
        SELECT 1
        FROM [ethnowear].[Users]
        WHERE [Id] = @UserId
          AND [PasswordHash] IS NULL
    )
        THROW 51501, 'A password must be assigned before enabling the user.', 1;

    IF NOT EXISTS
    (
        SELECT 1
        FROM [ethnowear].[UserRoles]
        WHERE [UserId] = @UserId
    )
        THROW 51502, 'At least one role must be assigned before enabling the user.', 1;

    IF EXISTS
    (
        SELECT 1
        FROM [ethnowear].[Users]
        WHERE [Id] = @UserId
          AND [MustChangePassword] = 1
          AND [TemporaryPasswordExpiresAt] <= SYSUTCDATETIME()
    )
        THROW 51503, 'The temporary password has expired.', 1;

    UPDATE [ethnowear].[Users]
    SET
        [Enabled] = 1,
        [UpdatedAt] = SYSUTCDATETIME()
    WHERE [Id] = @UserId;
END;

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @RoleName = UPPER(LTRIM(RTRIM(@RoleName)));

    DECLARE @RoleId BIGINT;

    SELECT @RoleId = [Id]
    FROM [ethnowear].[Roles]
    WHERE [Name] = @RoleName;

    IF @RoleId IS NULL
        THROW 51300, 'Role does not exist.', 1;

    IF NOT EXISTS
    (
        SELECT 1
        FROM [ethnowear].[Users]
        WHERE [Id] = @UserId
    )
        THROW 51302, 'User does not exist.', 1;

    IF @RoleName = N'ADMINISTRATOR'
       AND EXISTS
       (
           SELECT 1
           FROM [ethnowear].[Users]
           WHERE [Id] = @UserId
             AND [Enabled] = 1
       )
       AND (
           SELECT COUNT_BIG(*)
           FROM [ethnowear].[Users] AS [users]
           INNER JOIN [ethnowear].[UserRoles] AS [userRoles]
               ON [userRoles].[UserId] = [users].[Id]
           WHERE [users].[Enabled] = 1
             AND [userRoles].[RoleId] = @RoleId
       ) <= 1
        THROW 51301, 'The final enabled administrator cannot lose the administrator role.', 1;

    IF EXISTS
       (
           SELECT 1
           FROM [ethnowear].[Users]
           WHERE [Id] = @UserId
             AND [Enabled] = 1
       )
       AND (
           SELECT COUNT_BIG(*)
           FROM [ethnowear].[UserRoles]
           WHERE [UserId] = @UserId
       ) <= 1
        THROW 51303, 'An enabled user must retain at least one role.', 1;

    DELETE FROM [ethnowear].[UserRoles]
    WHERE [UserId] = @UserId
      AND [RoleId] = @RoleId;
END;

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @UserId IS NULL
        THROW 51000, 'User id is required.', 1;

    IF NOT EXISTS
    (
        SELECT 1
        FROM [ethnowear].[Users]
        WHERE [Id] = @UserId
    )
        THROW 51001, 'User does not exist.', 1;

    IF @PasswordHash IS NULL
       OR LEN(@PasswordHash) <> 68
       OR @PasswordHash NOT LIKE N'{bcrypt}$2[aby]$12$%'
        THROW 51002, 'A Spring delegated BCrypt hash with cost 12 is required.', 1;

    IF @MustChangePassword = 0 AND @TemporaryPasswordExpiresAt IS NOT NULL
        THROW 51003, 'A permanent password cannot have a temporary-password expiry.', 1;

    IF @MustChangePassword = 1
       AND (
           @TemporaryPasswordExpiresAt IS NULL
           OR @TemporaryPasswordExpiresAt <= SYSUTCDATETIME()
       )
        THROW 51004, 'A temporary password requires a future expiry.', 1;

    IF @EnableUser = 1
       AND NOT EXISTS
       (
           SELECT 1
           FROM [ethnowear].[UserRoles]
           WHERE [UserId] = @UserId
       )
        THROW 51005, 'At least one role must be assigned before enabling the user.', 1;

    UPDATE [ethnowear].[Users]
    SET
        [PasswordHash] = @PasswordHash,
        [MustChangePassword] = @MustChangePassword,
        [TemporaryPasswordExpiresAt] = @TemporaryPasswordExpiresAt,
        [Enabled] = @EnableUser,
        [FailedLoginAttempts] = 0,
        [LockedUntil] = NULL,
        [TokenVersion] = [TokenVersion] + 1,
        [UpdatedAt] = SYSUTCDATETIME()
    WHERE [Id] = @UserId;
END;

CREATE PROCEDURE [ethnowear].[SetUserPasswordHash]
    @UserId BIGINT,
    @PasswordHash NVARCHAR(255),
    @MustChangePassword BIT = 1,
    @TemporaryPasswordExpiresAt DATETIME2(7) = NULL,
    @EnableUser BIT = 1
AS

BEGIN SET NOCOUNT ON;
INSERT INTO [ethnowear].[DocumentProcessingJobAttempts] ( [ProcessingJobId], [ExecutionNumber], [AttemptNumber], [Status], [ClaimedBy], [ClaimedAt], [StartedAt], [FinishedAt], [ProcessorName], [ProcessorVersion], [ToolName], [ToolVersion], [ErrorCode], [SafeErrorMessage], [CancellationReason], [UpdatedAt] ) SELECT [current].[Id], ISNULL(( SELECT MAX([history].[ExecutionNumber]) FROM [ethnowear].[DocumentProcessingJobAttempts] [history] WHERE [history].[ProcessingJobId] = [current].[Id] ), 0) + 1, [current].[AttemptCount], [current].[Status], [current].[ClaimedBy], [current].[ClaimedAt], [current].[StartedAt], [current].[FinishedAt], [current].[ProcessorName], [current].[ProcessorVersion], [current].[ToolName], [current].[ToolVersion], [current].[ErrorCode], [current].[SafeErrorMessage], [current].[CancellationReason], [current].[UpdatedAt] FROM [inserted] [current] INNER JOIN [deleted] [previous] ON [previous].[Id] = [current].[Id] WHERE [current].[AttemptCount] > [previous].[AttemptCount] AND [current].[ClaimedAt] IS NOT NULL;
UPDATE [history] SET [Status] = [current].[Status], [ClaimedBy] = [current].[ClaimedBy], [StartedAt] = COALESCE([current].[StartedAt], [history].[StartedAt]), [FinishedAt] = [current].[FinishedAt], [ProcessorName] = [current].[ProcessorName], [ProcessorVersion] = [current].[ProcessorVersion], [ToolName] = [current].[ToolName], [ToolVersion] = [current].[ToolVersion], [ErrorCode] = [current].[ErrorCode], [SafeErrorMessage] = [current].[SafeErrorMessage], [CancellationReason] = [current].[CancellationReason], [UpdatedAt] = [current].[UpdatedAt] FROM [ethnowear].[DocumentProcessingJobAttempts] [history] INNER JOIN [inserted] [current] ON [current].[Id] = [history].[ProcessingJobId] INNER JOIN [deleted] [previous] ON [previous].[Id] = [current].[Id] WHERE [current].[AttemptCount] = [previous].[AttemptCount] AND [current].[AttemptCount] > 0 AND [history].[ExecutionNumber] = ( SELECT MAX([latest].[ExecutionNumber]) FROM [ethnowear].[DocumentProcessingJobAttempts] [latest] WHERE [latest].[ProcessingJobId] = [current].[Id] ); END;

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF NOT EXISTS
    (
        SELECT 1
        FROM [ethnowear].[Users]
        WHERE [Id] = @UserId
    )
        THROW 51700, 'User does not exist.', 1;

    UPDATE [ethnowear].[Users]
    SET
        [FailedLoginAttempts] = 0,
        [LockedUntil] = NULL,
        [UpdatedAt] = SYSUTCDATETIME()
    WHERE [Id] = @UserId;
END;

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @FirstName = LTRIM(RTRIM(@FirstName));
    SET @LastName = LTRIM(RTRIM(@LastName));
    SET @Email = NULLIF(LTRIM(RTRIM(@Email)), N'');
    SET @CountryCode = NULLIF(UPPER(LTRIM(RTRIM(@CountryCode))), N'');

    IF @FirstName IS NULL OR LEN(@FirstName) = 0
        THROW 51400, 'First name is required.', 1;

    IF @LastName IS NULL OR LEN(@LastName) = 0
        THROW 51401, 'Last name is required.', 1;

    IF @CountryCode IS NOT NULL AND @CountryCode NOT LIKE '[A-Z][A-Z]'
        THROW 51402, 'Country code must contain two uppercase letters.', 1;

    IF NOT EXISTS
    (
        SELECT 1
        FROM [ethnowear].[UserInfo]
        WHERE [UserId] = @UserId
    )
        THROW 51403, 'User profile does not exist.', 1;

    IF @Email IS NOT NULL
       AND EXISTS
       (
           SELECT 1
           FROM [ethnowear].[UserInfo]
           WHERE [NormalizedEmail] = UPPER(@Email)
             AND [UserId] <> @UserId
       )
        THROW 51404, 'Email address already exists.', 1;

    UPDATE [ethnowear].[UserInfo]
    SET
        [FirstName] = @FirstName,
        [LastName] = @LastName,
        [Email] = @Email,
        [Phone] = @Phone,
        [AddressLine1] = @AddressLine1,
        [AddressLine2] = @AddressLine2,
        [City] = @City,
        [PostalCode] = @PostalCode,
        [CountryCode] = @CountryCode,
        [UpdatedAt] = SYSUTCDATETIME()
    WHERE [UserId] = @UserId;
END;

